  import java.util.Map;
  import java.util.HashMap;

  import org.apache.log4j.Logger;

  Logger logger = Logger.getLogger("iiq.alpha.Alpha-Rule-WebServiceBeforeOperation-HRSoft");
  if (logger.isTraceEnabled()) {
    logger.trace("Entered to Alpha-Rule-WebServiceBeforeOperation-HRSoft!!");
  }

  Map contextAttributeMap = null;
  logger.debug("Context Property Attribute Map : "+context.getProperty("contextAttributeMap"));
  contextAttributeMap = context.getProperty("contextAttributeMap");
  String firstName = null;
  firstName = (String) contextAttributeMap.get("#plan.firstName#");
  logger.debug("First Name from Context : "+firstName);

  if (requestEndPoint.getOperationType().equalsIgnoreCase("Add Entitlement")) {
    logger.debug(requestEndPoint.getOperationType()+" Operation starts");

    Map bodyMap = requestEndPoint.getBody();
    String requestBody = bodyMap.get("jsonBody");

    logger.debug("Request Body - Before changes : "+requestBody);

    requestBody = requestBody.replace("#plan.firstName#", firstName);

    logger.debug("Request Body - After changes : "+requestBody);

    Map newBodyMap = new HashMap();
    newBodyMap.put("jsonBody", requestBody);
    newBodyMap.put("bodyFormat", "raw");
    requestEndPoint.setBody(newBodyMap);
  }

  if (logger.isTraceEnabled()) {
    logger.trace("Alpha-Rule-WebServiceBeforeOperation-HRSoft Rule is Ended!!");
  }
